use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] #[ORM\Index(columns:['landed_cost','in_stock'])] class Offer { #[ORM\Id, ORM\GeneratedValue, ORM\Column] private ?int $id=null; #[ORM\ManyToOne] #[ORM\JoinColumn(nullable:false)] public Product $product; #[ORM\ManyToOne] #[ORM\JoinColumn(nullable:false)] public Store $store; #[ORM\Column(length:500)] public string $url=''; #[ORM\Column(length:220)] public string $title=''; #[ORM\Column] public float $price=0; #[ORM\Column] public float $shipping=0; #[ORM\Column] public float $landedCost=0; #[ORM\Column(length:3)] public string $currency='EUR'; #[ORM\Column] public bool $inStock=true; #[ORM\Column(length:12)] public string $costConfidence='low'; #[ORM\Column] public int $matchConfidence=0; #[ORM\Column] public \DateTimeImmutable $checkedAt; #[ORM\Column(nullable:true)] public ?int $displayCount=1; #[ORM\Column(nullable:true)] public ?float $unitCost=null; #[ORM\Column] public bool $shippingKnown=false; #[ORM\Column(type:'json', nullable:true)] public ?array $shippingOrigin=null; public function __construct(){ $this->checkedAt=new \DateTimeImmutable(); } public function getId():?int{return $this->id;} }
